import raw from './questions.json';
import { ENGLISH_ID, MOCK_FORMAT } from './catalog';
import type { ClassLevel, Question, QuestionBank, Topic } from './types';

/** Generated by `npm run build-questions` from content/questions/*.txt. Do not edit by hand. */
export const bank = raw as unknown as QuestionBank;

const byId = new Map(bank.questions.map(q => [q.id, q]));

export const topicsFor = (subjectId: string, level?: ClassLevel): Topic[] =>
  bank.topics.filter(t => t.subjectId === subjectId && (!level || t.level === level));
export const questionsFor = (subjectId: string, topicId?: string): Question[] =>
  bank.questions.filter(q => q.subjectId === subjectId && (!topicId || q.topicId === topicId));
export const questionById = (id: string) => byId.get(id);

/** Fisher–Yates shuffle. `rand` is injectable so tests can be deterministic. */
export function shuffle<T>(items: readonly T[], rand: () => number = Math.random): T[] {
  const a = [...items];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/**
 * Picks up to `count` questions, spread across topics so one topic doesn't dominate.
 * Within each topic, questions the student hasn't answered yet come first.
 */
export function pickQuestions(pool: Question[], count: number, answered: (id: string) => boolean = () => false, rand: () => number = Math.random): Question[] {
  const fresh = shuffle(pool.filter(q => !answered(q.id)), rand);
  const seen = shuffle(pool.filter(q => answered(q.id)), rand);
  const byTopic = new Map<string, Question[]>();
  for (const q of [...fresh, ...seen]) byTopic.set(q.topicId, [...(byTopic.get(q.topicId) ?? []), q]);
  const queues = shuffle([...byTopic.values()], rand);
  const picked: Question[] = [];
  while (picked.length < count && queues.some(q => q.length)) {
    for (const queue of queues) {
      const next = queue.shift();
      if (next && picked.length < count) picked.push(next);
    }
  }
  return picked;
}

/** English first, then the student's other subjects, each with a random spread of questions. */
export function buildMock(subjectIds: string[], questions: Question[] = bank.questions, rand: () => number = Math.random): string[] {
  const order = [ENGLISH_ID, ...subjectIds.filter(s => s !== ENGLISH_ID)];
  return order.flatMap(subjectId =>
    pickQuestions(questions.filter(q => q.subjectId === subjectId), MOCK_FORMAT.questionsPerSubject, undefined, rand).map(q => q.id));
}
